'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm'),path=require('node:path');
class Element{constructor(){this.children=[];this.listeners={};this.hidden=true;this.value='';this.textContent='';this.classList={toggle(){}};}append(...x){this.children.push(...x);}replaceChildren(...x){this.children=x;}addEventListener(k,f){this.listeners[k]=f;}setAttribute(){}querySelector(){return {disabled:false};}}
const html=fs.readFileSync(path.join(__dirname,'../assets/index.html'),'utf8');
for(const id of ['sync-issues','sync-issue-list','sync-issue-count','sync-attention'])assert.ok(html.includes('id="'+id+'"'),'missing live page element '+id);
const elements=new Map(),el=id=>{if(!elements.has(id))elements.set(id,new Element());return elements.get(id);};
const context={document:{getElementById:el,createElement:()=>new Element(),querySelectorAll:()=>[]},window:{DriveBridgeAuth:require('../assets/auth-view.js'),DriveBridgeDiff:{},DriveBridgeBatch:require('../assets/batch-view.js'),DriveBridgeRecovery:require('../assets/recovery-view.js'),DriveBridgeDiscovery:{create:()=>({})},addEventListener(){}},URLSearchParams};
let source=fs.readFileSync(path.join(__dirname,'../assets/app.js'),'utf8');
source=source.replace('  start();','  globalThis.renderIssues=renderIssues;');
vm.runInNewContext(source,context);
const issue={job_id:'job',name:'手册.md',code:'unsupported_content',new_document:true,local_saved:true,can_download:true};
context.renderIssues([{id:'mount',state:{running:true,issues:[issue]}}],true);
assert.equal(el('sync-issues').hidden,false,'blocked uploads need a persistent visible panel');
const texts=e=>[e.textContent,...e.children.flatMap(texts)].join(' ');
assert.match(texts(el('sync-issue-list')),/手册.md/);assert.match(texts(el('sync-issue-list')),/新文档|关联/);assert.match(texts(el('sync-issue-list')),/本地.*保存/);assert.match(texts(el('sync-issue-list')),/副本/);
const walk=e=>[e,...e.children.flatMap(walk)];
assert.ok(walk(el('sync-issue-list')).some(e=>e.href==='/api/mounts/mount/uploads/job/local'),'download must use the captured job, not a filesystem path');
assert.ok(!walk(el('sync-issue-list')).some(e=>e.textContent==='重试同步'),'unsupported content must not present retry as a fix');
context.renderIssues([{id:'mount',state:{running:true,issues:[{...issue,code:'network_or_protocol'}]}}],true);
assert.ok(walk(el('sync-issue-list')).some(e=>e.textContent==='重试同步'),'transient failures need a retry action');
context.renderIssues([{id:'mount',status_warning:'pending',state:{running:true,issues:[issue]}}],true);
assert.match(texts(el('sync-issue-list')),/上次|更新/,'stale issues must be labeled');
context.renderIssues([{id:'mount',state:{running:true,cloud_state:'blocked',last_error:'unsupported_content'}}],true);
assert.equal(el('sync-issues').hidden,false,'legacy backend errors cannot disappear when no detail is available');
context.renderIssues([{id:'mount',state:{running:true,issues:[]}}],true);assert.equal(el('sync-issues').hidden,true);
console.log('blocked upload visibility, advice, safe copy, retry and stale fallback verified');

context.renderIssues([{id:'mount',state:{running:true,issues:[{...issue,code:'history_git_unavailable'}]}}],true);
assert.match(texts(el('sync-issue-list')),/内置 Git/);
assert.match(texts(el('sync-issue-list')),/重新安装应用/);
assert.ok(!walk(el('sync-issue-list')).some(e=>e.textContent==='重试同步'),'missing Git requires repairing the app before retrying');

const markup = '<script>unsafe user text</script>';
context.renderIssues([{id:'mount',state:{running:true,issues:[{...issue,diagnostic:{kind:'html_block',message:'Unsupported HTML block',line:3,end_line:5,text:markup,side:'local'}}]}}],true);
assert.match(texts(el('sync-issue-list')),/错误类型：html_block/);
assert.match(texts(el('sync-issue-list')),/本地第 3–5 行/);
assert.ok(walk(el('sync-issue-list')).some(e=>e.textContent===markup),'captured user text is rendered with textContent');
assert.ok(!walk(el('sync-issue-list')).some(e=>e.innerHTML?.includes(markup)),'diagnostic text never enters HTML');
console.log('captured diagnostic type, source lines and text are visible safely');

const recovering={...issue,code:'creation_needs_attention',create_recovery:{can_recreate:true,current_generation:9,current_local:'a'.repeat(64),attempts:3,reason:'location_changed'}};
context.renderIssues([{id:'mount',state:{running:true,issues:[recovering]}}],true,true);
assert.ok(walk(el('sync-issue-list')).some(e=>e.textContent==='重新核验'));
assert.ok(walk(el('sync-issue-list')).some(e=>e.textContent==='重新创建…'));
assert.match(texts(el('sync-issue-list')),/3 次/);
assert.match(texts(el('sync-issue-list')),/名称或位置已变化/);
assert.match(texts(el('sync-issue-list')),/最新本地版本/);
assert.ok(!walk(el('sync-issue-list')).some(e=>e.textContent==='重试同步'));
context.renderIssues([{id:'mount',state:{running:true,issues:[{...recovering,create_recovery:{...recovering.create_recovery,can_recreate:false}}]}}],true,true);
assert.ok(!walk(el('sync-issue-list')).some(e=>e.textContent==='重新创建…'));

(async()=>{
 context.renderIssues([{id:'mount',state:{running:true,issues:[recovering,{...recovering,job_id:'other-job',name:'其他.md'}]}}],true,true);
 let buttons=walk(el('sync-issue-list')).filter(e=>e.textContent==='重新创建…');
 let requests=[],release;
 context.window.confirm=()=>false;
 context.fetch=async(route,options)=>{requests.push({route,options});if(route==='/api/status')return {ok:true,json:async()=>({mounts:[],conflicts:[]})};await new Promise(r=>release=r);return {ok:true,json:async()=>({accepted:true})};};
 await buttons[0].listeners.click();assert.equal(requests.length,0,'canceling confirmation cannot send recovery');
 let prompt='';context.window.confirm=text=>{prompt=text;return true;};
 const pending=buttons[0].listeners.click();
 assert.match(prompt,/旧副本.*移动/);assert.match(prompt,/最新本地版本/);
 assert.equal(buttons[0].disabled,true);assert.equal(Boolean(buttons[1].disabled),false,'other files remain actionable');
 assert.equal(requests[0].route,'/api/mounts/mount/uploads/job/recover');
 assert.deepEqual(JSON.parse(requests[0].options.body),{action:'recreate',expected_generation:9,expected_local:'a'.repeat(64),confirm_recreate:true});
 release();await pending;
 context.renderIssues([{id:'mount',state:{running:true,issues:[recovering]}}],true,true);
 context.fetch=async(route)=>route==='/api/status'?{ok:true,json:async()=>({mounts:[],conflicts:[]})}:{ok:false,status:409,json:async()=>({code:'creation_unconfirmed',message:'创建结果尚未确认，请重新核验。'})};
 await walk(el('sync-issue-list')).find(e=>e.textContent==='重新核验').listeners.click();
 assert.match(el('message').textContent,/创建结果尚未确认/,'unconfirmed results must retain their typed explanation');
 console.log('create recovery confirmation, current snapshot and per-file isolation verified');
})().catch(error=>{console.error(error);process.exitCode=1;});
